package com.therighthon.rnr.common;
import com.therighthon.rnr.RoadsAndRoofs; import java.util.*; import java.util.function.*; import net.minecraft.resources.ResourceLocation; import net.minecraft.world.item.ItemStack; import net.minecraft.world.level.block.Block;
public final class RNRUtil { public static ResourceLocation identifier(String s){return new ResourceLocation(RoadsAndRoofs.MOD_ID,s);} public static boolean isItem(ItemStack s,net.minecraft.tags.TagKey<net.minecraft.world.item.Item> t){return s.is(t);} public static boolean isBlock(net.minecraft.world.level.block.state.BlockState s,net.minecraft.tags.TagKey<Block> t){return s.is(t);} public static <E extends Enum<E>,V> Map<E,V> mapOfKeys(Class<E> c,Function<E,V> f){Map<E,V> m=new LinkedHashMap<>();for(E e:c.getEnumConstants())m.put(e,f.apply(e));return m;} public static <E extends Enum<E>,V> Map<E,V> mapOfKeys(Class<E> c,Predicate<E> p,Function<E,V> f){Map<E,V> m=new LinkedHashMap<>();for(E e:c.getEnumConstants())if(p.test(e))m.put(e,f.apply(e));return m;} private RNRUtil(){} }
